import React, { useState, useEffect } from "react";
import EmployeTable from "./EmployeTable";
import MateriauTable from "./MateriauTable";
import DevisCard from "./DevisCard";
import { listerEmployesDisponibles } from "../services/employeService";
import { listerProjets } from "../services/projetService";

export default function Dashboard() {
    const [employes, setEmployes] = useState([]);
    const [projets, setProjets] = useState([]);
    const [selectedProjet, setSelectedProjet] = useState(null);

    useEffect(() => {
        listerEmployesDisponibles().then(setEmployes);
        listerProjets().then(setProjets);
    }, []);

    return (
        <div className="p-6">
            <h2 className="text-xl font-bold mb-4">Tableau de bord BTP</h2>

            {/* Sélection du projet */}
            <div className="mb-4">
                <label className="font-semibold mr-2">Choisir un projet :</label>
                <select
                    className="border p-1 rounded"
                    onChange={e => {
                        const projet = projets.find(p => p.id === parseInt(e.target.value));
                        setSelectedProjet(projet);
                    }}
                >
                    <option value="">-- Aucun --</option>
                    {projets.map(p => (
                        <option key={p.id} value={p.id}>
                            {p.typeConstruction} - Terrain {p.terrain?.localisation || ""}
                        </option>
                    ))}
                </select>
            </div>

            {/* Carte du devis */}
            {selectedProjet && <DevisCard projet={selectedProjet} />}

            <div className="flex gap-6 mt-6">
                {/* Tableau employés */}
                <div className="flex-1">
                    <h3 className="font-bold mb-2">Employés disponibles</h3>
                    <EmployeTable employes={employes} />
                </div>

                {/* Tableau matériaux */}
                {selectedProjet && (
                    <div className="flex-1">
                        <h3 className="font-bold mb-2">Matériaux du projet</h3>
                        <MateriauTable materiaux={selectedProjet.materiaux || []} />
                    </div>
                )}
            </div>
        </div>
    );
}
